('006.01.05.004', '4 anos', NULL, 2, 'Decreto Estadual n. 48.897/2004; Instrução Normativa APE/SAESP-2/2010. O Edital de ciência de eliminação de documentos visa dar publicidade à eliminação de documentos públicos.'),
