('006.01.06.002', 'Vigência', NULL, 2, 'Decreto Estadual n. 48.898/2004. A vigência esgota-se com a oficialização de nova tabela de temporalidade.'),
('006.01.06.003', 'Vigência', '5 anos', 2, 'Decreto Estadual n. 22.789/1984; Decreto Estadual n. 29.838/1989; Decreto Estadual n.48.897/2004; Decreto Estadual n. 48.898/2004. A vigência esgota-se com a publicação do Plano de Classificação e da Tabela de Temporalidade de Documentos no Diário Oficial.'),
('006.01.06.004', 'Vigência', '5 anos', 2, 'Decreto Estadual n.48.897/2004; Instrução Normativa APE/SAESP-2/2010. A vigência esgota-se com a assinatura do Termo de eliminação de documentos. Integram o Processo de eliminação de documentos a Relação de eliminação de documentos, a cópia do Edital de ciência de eliminação de documentos, e o Termo de eliminação de documentos.'),
('006.01.06.006', 'Vigência', '5 anos', 2, 'Decreto Estadual n. 48.897/2004; Instrução Normativa APE/SAESP-2/2010. A vigência esgota-se com a assinatura do Termo de transferência de documentos. Integram o Processo de transferência de documentos a Relação de transferência de documentos, o Termo de transferência de documentos e seus instrumentos de controle e pesquisa.'),
('006.01.06.007', 'Vigência', '12 anos', 1, 'Decreto Estadual n. 29.838/1989; Decreto Estadual n. 68.155/2023. A vigência esgota-se quando oficialmente houver extinção, dissolução, fusão, cisão, incorporação, transformação ou privatização do órgão/entidade. Constam do Dossiê a cópia do ato de criação da comissão, atas, ofícios, relatórios, e demais documentos produzidos e recebidos pela Comissão de Avaliação de Documentos e Acesso - CADA.'),
('006.01.07.001', 'Vigência', NULL, 1, 'Lei Federal n. 10.753/2003. A vigência esgota-se com a elaboração de uma nova ficha ou quando ocorrer a baixa patrimonial.'),
