('006.02.01.001', 'Vigência', NULL, 1, 'Lei Federal n. 9.610/1998; Instrução Normativa APE/SAESP-1/2009. A destinação das bases de dados está condicionada ao valor de suas informações para a Administração Estadual e para o público em geral. Somente deverão ser providenciadas cópias anuais para guarda permanente as bases de dados consideradas de valor histórico, informativo ou probatório.'),
('006.02.01.002', 'Vigência', '5 anos', 2, 'O documento registra as diretrizes definidas para a área de informática.'),
('006.02.01.003', 'Vigência', '5 anos', 2, ''),
('006.02.01.004', 'Vigência', '12 anos', 2, 'Lei Federal n. 9.609/1998; Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III. A vigência compreende o tempo de utilização do programa, bem como de todas as suas atualizações.'),
