('001.01.03.006', 'Até a aprovação das contas', '12 anos', 1, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Decreto Estadual n. 66.173/2021. Trata-se de convênios firmados com prefeituras e outras entidades para o atendimento de finalidades específicas e, em geral, rotineiras, como fornecimento de merenda e transporte escolar, cessão de prédios e funcionários, contratação de estudantes como estagiários, assessoria jurídica a pessoas presas, execução de obras e programas do estado de São Paulo, acesso a crédito, transferência de recursos financeiros, complementação de assistência à saúde nos municípios, qualificação profissional, entre outros. Os processos serão submetidos a procedimento estatístico para a retirada de amostras representativas destinadas à guarda permanente com vistas à preservação da memória administrativa, conforme Instrução Normativa APE/SAESP n. 3/2015. Não havendo repasse de recursos, a vigência esgota-se com o término do convênio.'),
('001.01.03.007', 'Vigência', '5 anos', 2, 'Decreto Estadual n. 66.173/2021. Trata-se de acordo, parceria ou cooperação técnica em que dois órgãos ou entidades, utilizando-se de sua expertise técnica, conjugam esforços para a consecução de um fim comum e para a produção de inovação e conhecimento. A vigência esgota- se com o término do acordo. O documento é importante para a preservação da memória institucional e para a produção de conhecimento.'),
