('002.01.04.001', 'Vigência', NULL, 2, 'Deve-se providenciar, anualmente, cópia da última versão para guarda permanente. Se o serviço for terceirizado, a contratada deverá providenciar a referida cópia e encaminhá-la ao órgão contratante.'),
('002.01.04.002', '4 anos', '4 anos', 2, 'Quando o serviço for terceirizado, a contratada deverá providenciar cópia dos registros e encaminhá-la ao órgão contratante.'),
