('002.03.01.015', 'Vigência', '20 anos', 1, 'Decreto Estadual n. 64.353/2019. A vigência esgota-se com a concessão das condecorações, medalhas e outras honorificências. O expediente deverá ser aberto a cada solicitação de condecorações, medalhas e outras honorificências.'),
('002.04.01.001', 'Vigência', NULL, 2, 'A vigência esgota-se com a elaboração de novo projeto.'),
