('002.04.02.002', 'Vigência', NULL, 1, 'Decreto Estadual n. 69.745/2025, art. 17, III e art. 30, II, a. O documento integra o Processo de contratação de agência de publicidade. As cópias podem ser eliminadas após sua vigência na própria Unidade Produtora.'),
('002.04.02.003', 'Até a aprovação das contas', '12 anos', 2, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Lei Federal n. 14.133/2021; Lei Complementar Estadual n. 709/1993. As guias de recolhimento de encargos sociais devem ser arquivadas em separado e obedecerão aos prazos previstos nesta tabela, na atividade “Controle da contabilidade”. O processo deve ser preservado pois contém peças de campanha publicitária, bem como o Briefing e o Plano de mídia.'),
('002.04.03.001', 'Vigência', NULL, 1, ''),
