('006.01.06.007', 'Vigência', '12 anos', 1, 'Decreto Estadual n. 29.838/1989; Decreto Estadual n. 68.155/2023. A vigência esgota-se quando oficialmente houver extinção, dissolução, fusão, cisão, incorporação, transformação ou privatização do órgão/entidade. Constam do Dossiê a cópia do ato de criação da comissão, atas, ofícios, relatórios, e demais documentos produzidos e recebidos pela Comissão de Avaliação de Documentos e Acesso - CADA.'),
