('003.03.01.004', 'Vigência', '5 anos', 1, 'Lei Estadual n. 180/1978, arts. 52 a 57. O ato que autoriza a mobilidade integra o Prontuário funcional. A vigência esgota-se com o encerramento dos procedimentos administrativos e o arquivamento do processo.'),
('003.03.01.005', 'Vigência', '5 anos', 2, 'Lei Estadual n. 3.159/1955, art. 2º, parágrafo único; Decreto-Lei Estadual n. 13.654/1943, art. 20. O ato que autoriza a promoção integra o Prontuário funcional. A vigência esgota-se com o encerramento dos procedimentos administrativos e o arquivamento do processo.'),
('003.03.01.006', 'Vigência', '5 anos', 1, 'O ato que autoriza a promoção integra o Prontuário funcional. A vigência esgota-se com o encerramento dos procedimentos administrativos e o arquivamento do processo.'),
