('003.03.02.006', 'Vigência', '10 anos', 1, 'Lei Complementar Estadual n. 180/1978, art. 59, I. O ato de dispensa integra o Prontuário funcional. A vigência esgota-se com o encerramento dos procedimentos administrativos e o arquivamento do processo.'),
('003.03.02.007', 'Vigência', '10 anos', 1, 'Lei Complementar Estadual n. 180/1978, art. 58, I. O ato de exoneração integra o Prontuário funcional. A vigência esgota-se com o encerramento dos procedimentos administrativos e o arquivamento do processo.'),
('003.03.02.008', 'Vigência', '5 anos', 1, 'Lei Complementar Estadual n. 180/1978, arts. 80- 82. O ato que autoriza a substituição integra o Prontuário funcional. A vigência esgota-se com o encerramento dos procedimentos administrativos e o arquivamento do processo.'),
('003.03.02.009', 'Até a aprovação das contas', '5 anos', 1, 'Lei Federal n. 9.601/1998; Lei Complementar Estadual n. 180/1978; Lei Complementar Estadual n. 709/1993; Instruções TCESP n. 1/2024. São formas de preenchimento de funções-atividades: a admissão, a transposição, o acesso e a reversão.'),
('003.03.02.010', 'Até a aprovação das contas', '5 anos', 1, 'Lei Complementar Estadual n. 180/1978; Lei Complementar Estadual n. 709/1993; Instruções TCESP n. 1/2024. São formas de provimento de cargos: a nomeação, a transposição, o acesso, a reintegração, a reversão, o aproveitamento e a readmissão.'),
('003.03.02.011', 'Até a aprovação das contas', '5 anos', 1, 'Lei Complementar Estadual n. 709/1993.'),
