('004.01.01.001', 'Vigência', '12 anos', 1, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Lei Federal n.14.133/2021; Lei Federal n. 10.028/2000. Os contratos integram os Processos de aquisição, de contratação de serviços ou obras e os convênios, e obedecerão à temporalidade e destinação dos respectivos processos. As guias de recolhimento da Previdência Social e outros impostos deverão ser arquivadas em separado e obedecerão aos prazos previstos nesta tabela, na atividade “Controle da contabilidade”.'),
