('004.01.04.005', 'Vigência', '1 ano', 1, 'Trata-se de expediente preliminar ao Processo de prestação de contas de adiantamento. A vigência esgota-se com o despacho do responsável negando a realização do gasto. Caso a requisição seja atendida o Expediente deve ser incorporado ao respectivo Processo de prestação de contas de adiantamento, seguindo os prazos de guarda e a destinação deste.'),
('004.01.04.006', 'Até aprovação das contas', '12 anos', 1, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Lei Federal n. 14.133/2021; Lei Complementar Estadual n. 709/1993. Processo aberto em decorrência de processo de aquisições continuadas e ao qual deve sempre fazer referência.'),
('004.01.05.001', 'Até a aprovação das contas', '12 anos', 1, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Lei Federal n.10.028/2000; Lei Complementar Estadual n. 709/1993; Lei Federal n.14.133/2021. Considera-se obra toda construção, reforma, fabricação, recuperação, restauro, demolição ou ampliação, realizada por execução direta ou indireta.'),
('004.01.05.002', 'Até a aprovação das contas', '12 anos', 1, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Lei Federal n.10.028/2000; Lei Complementar Estadual n. 709/1993. Lei Federal n.14.133/2021. As guias de recolhimento de encargos sociais devem ser arquivadas em separado e obedecerão aos prazos previstos nesta tabela, na atividade “Controle da contabilidade”.'),
('004.01.05.003', 'Até a aprovação das contas', '12 anos', 1, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Lei Federal n.10.028/2000; Lei Complementar Estadual n. 709/1993; Lei Federal n.14.133/2021. As guias de recolhimento de encargos sociais devem ser arquivadas em separado e obedecerão aos prazos previstos nesta tabela, na atividade “Controle da contabilidade”.'),
('004.01.05.004', 'Até a aprovação das contas', '12 anos', 1, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Lei Federal n.10.028/2000; Lei Complementar Estadual n. 709/1993. Lei Federal n.14.133/2021. As guias de recolhimento de encargos sociais devem ser arquivadas em separado e obedecerão aos prazos previstos nesta tabela, na atividade “Controle da contabilidade”.'),
('004.01.05.006', 'Até a aprovação das contas', '12 anos', 1, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Lei Federal n.10.028/2000; Lei Complementar Estadual n. 709/1993.Lei Federal n.14.133/202. As guias de recolhimento de encargos sociais devem ser arquivadas em separado e obedecerão aos prazos previstos nesta tabela, na atividade “Controle da contabilidade”.'),
('004.01.05.007', 'Até a aprovação das contas', '60 anos', 1, 'Lei Federal n. 10.406/2002 (Código Civil). As guias de recolhimento de encargos sociais devem ser arquivadas em separado e obedecerão aos prazos previstos nesta tabela, na atividade “Controle da contabilidade”. Os processos podem ser eliminados após os 60 anos na Unidade com atribuições de Arquivo, com a condição de se proceder ao desentranhamento dos projetos, quando houver, para guarda permanente.'),
('004.01.05.008', 'Vigência', '5 anos', 2, 'A vigência esgota-se com o término do projeto. O Projeto de obra pública que envolva repasse de verba Federal ou Estadual deve ser apensado ao Processo de contratação de obra pública e desapensado após o seu encerramento, devendo essa informação constar do processo principal.'),
('004.01.05.009', 'Até a aprovação das contas', '12 anos', 1, 'Decreto-Lei Federal n. 2.848/1940 (Código Penal), art. 109, III; Lei Federal n. 14.133/2021, art. 141; Lei Complementar Estadual n. 709/1993. Processo aberto em decorrência de processo de contratação de serviços continuados e ao qual deve sempre fazer referência.'),
