('006.01.09.002', '1 ano', NULL, 1, 'Trata-se de cópia, pois o documento foi encaminhado ao interessado.'),
('006.01.09.003', '1 ano', NULL, 1, ''),
('006.01.10.001', '2 anos', NULL, 1, 'A correspondência interna que veicula conteúdos rotineiros, em geral não implica em continuidade administrativa. Quando o documento integrar um processo obedecerá a sua temporalidade e à sua destinação.'),
('006.01.10.002', 'Vigência', NULL, 1, 'A vigência esgota-se com a realização do evento.'),
('006.01.10.003', '2 anos', NULL, 1, 'A correspondência que registra relações interinstitucionais ou com a comunidade pode provocar desdobramentos e, de acordo com a natureza de seu conteúdo, definirá a temporalidade do processo ou expediente que iniciar. A eliminação está condicionada à inexistência de fatores determinantes de sua guarda.'),
('006.01.10.004', 'Vigência', '2 anos', 1, 'Trata-se de respostas às correspondências recebidas. Quando a correspondência ensejar outras providências ou desdobramentos o documento deverá ser reclassificado de acordo com a natureza de seu conteúdo. A vigência esgota-se com o encaminhamento da resposta ao interessado.'),
('006.01.10.005', '2 anos', NULL, 1, 'Caso o documento integre um documento composto, seguirá os prazos e a destinação deste.'),
('006.01.11.001', 'Vigência', '2 anos', 2, 'A vigência esgota-se com o término da exposição.'),
('006.01.11.002', 'Vigência', '2 anos', 1, 'Trata-se de livro que registra cumprimentos, impressões e comentários. A vigência perdura até completar o livro.'),
