('002.01.02.005', 'Vigência', NULL, 2, 'Quando houver alterações substantivas no layout ou no conteúdo do site, deve-se providenciar cópia da versão anterior para guarda permanente. Se o serviço for terceirizado, a contratada deverá providenciar cópia dos registros e encaminhá-la ao órgão contratante.'),
