('002.04.03.004', '4 anos', NULL, 1, ''),
('002.04.03.005', '4 anos', NULL, 1, 'Decreto estadual n. 69.745/2025. O ofício pode solicitar ou autorizar serviços de comunicação, campanhas de publicidade, ou, ainda, aprovar programas de trabalho. Dependendo do caso, o documento integra o Processo de contratação de serviços de publicidade.'),
('002.04.03.006', '4 anos', NULL, 1, 'Decreto estadual n. 69.745/2025. Se o pedido for aprovado, o documento integrará o Processo de contratação de agência de publicidade. O pedido é, geralmente, formalizado por ofício.'),
('002.04.03.007', 'Vigência', NULL, 1, 'Decreto estadual n. 69.745/2025. O documento integra o Processo de contratação de serviços de publicidade.'),
('002.04.04.001', 'Vigência', NULL, 2, 'Decreto estadual n. 69.745/2025. Se o serviço for terceirizado, a contratada deve fornecer cópia do documento para o órgão contratante.'),
('002.04.04.002', '4 anos', NULL, 1, ''),
('002.04.04.003', 'Vigência', '2 anos', 1, 'O documento integra o Processo de contratação de agência de publicidade. As cópias podem ser eliminadas após sua vigência na própria Unidade Produtora.'),
('002.04.04.005', 'Vigência', '5 anos', 1, 'O documento integra o Processo de contratação de agência de publicidade e suas informações podem ser recuperadas no Cadastro de despesas de comunicação.'),
('002.04.04.006', 'Vigência', NULL, 2, 'Quando o serviço for terceirizado, a contratada deverá providenciar cópia dos registros e encaminhá-la ao órgão contratante.'),
('002.05.01.001', '2 anos', NULL, 2, 'Decreto estadual n. 69.052/2024. Trata-se de publicações em geral, como livro, periódico, cartilha, roteiro, manual, folheto, fôlder, flyer, cartaz institucional, vídeo, e-book. Um exemplar das publicações oficiais ou co-edições (livros ou periódicos) dos órgãos e entidades da administração pública estadual deve ser encaminhado ao Arquivo Público do Estado para guarda permanente e acesso público em sua Biblioteca.'),
