('003.03.04.004', '1 ano', NULL, 1, 'O pedido é feito com formulário próprio e encaminhado por ofício.'),
('003.03.04.005', 'Vigência', '5 anos', 1, 'A vigência esgota-se com concessão do benefício. As informações constam da Ficha de registro de frequência (modelo 100) e todos os atos de concessão e incorporação integram o Processo Único de Contagem de Tempo - PUCT. O ato administrativo que concede o afastamento ou a licença integra o Prontuário funcional.'),
('003.03.04.006', 'Vigência', '60 anos', 1, 'Instruções TCESP n. 1/2024; Portaria SPPREV n. 25/2012. A vigência esgota-se com o falecimento do aposentado ou, se houver beneficiário, quando o direito deste à pensão extinguir-se.'),
('003.03.04.007', 'Vigência', '10 anos', 1, 'Lei Federal n. 10.406/2002 (Código Civil), art. 205; Lei Estadual n. 10.394/1970; Lei Estadual n. 10.393/1970; Lei Estadual n. 7.384/1962. A vigência esgota-se com o falecimento do aposentado ou, se houver beneficiário, quando o direito deste à pensão extinguir-se.'),
('003.03.04.009', 'Vigência', '60 anos', 1, 'Instruções TCESP n. 1/2024. A vigência esgota- se com o rompimento do vínculo jurídico com o Estado. O ato integra o Processo Único de Contagem de Tempo - PUCT.'),
('003.03.04.010', 'Vigência', '5 anos', 1, 'Lei Federal n. 5.172/1966 (Código Tributário Nacional); Lei Federal n. 8.213/1991; Portaria SPPREV n. 25/2012. O ato administrativo que concede o direito ou o benefício integra o Prontuário funcional.'),
('003.03.04.011', 'Vigência', '5 anos', 1, 'Constituição Estadual/1989; Lei Estadual n. 10.168/1968; Lei Complementar Estadual n. 180/1978; Lei Complementar Estadual n. 813/1996; Lei Complementar Estadual n. 847/1998. A vigência esgota-se com a aposentadoria ou com o rompimento do vínculo jurídico com o Estado. Todos os atos de concessão e incorporação integram o Processo Único de Contagem de Tempo - PUCT.'),
('003.03.04.012', 'Vigência', '5 anos', 1, 'Constituição Estadual/1989. A vigência esgota-se com o deferimento da incorporação total dos décimos.'),
('003.03.04.013', 'Vigência', '5 anos', 1, 'Lei Estadual n. 10.261/1968.'),
('003.03.04.014', 'Vigência', '10 anos', 1, 'Lei Federal n. 10.406/2002 (Código Civil), art. 205; Lei Estadual n. 180/1978; Instruções TCESP n. 1/2024. A vigência esgota-se com a extinção da pensão mensal, que ocorre com a morte, casamento, cessação da incapacidade ou invalidez, ou com o implemento da idade do pensionista.'),
('003.03.04.016', 'Vigência', '60 anos', 1, 'Decreto-Lei Estadual n. 260/1970; Instruções TCESP n. 1/2024. A vigência esgota-se quando o direito do reformado e de seus beneficiários extinguir-se. O ato integra o Assentamento Individual do Policial Militar e o Processo Único de Contagem de Tempo - PUCT.'),
