('003.03.07.005', 'Vigência', '10 anos', 1, 'Lei Complementar Estadual n. 942/2003; Lei Estadual n. 10.261/1968. O Processo de revisão deverá ser apensado ao Processo administrativo ou ao Processo de sindicância. A vigência esgota- se com a conclusão da revisão. A decisão deverá ser averbada no Prontuário funcional.'),
('003.03.07.006', 'Vigência', '10 anos', 1, 'Lei Estadual n. 10. 261/1968. Lei Federal n. 10.406/2002 (Código Civil), art. 205. A vigência esgota-se com o pedido de exoneração ou com aplicação da pena disciplinar. A decisão deverá ser averbada no Prontuário funcional.'),
('003.03.07.009', 'Vigência', '10 anos', 2, 'Lei Complementar Estadual n. 207/1979; Lei Complementar Estadual n. 922/2002; Lei Complementar Estadual n. 942/2003; Lei Estadual n. 10.261/1968. Será instaurado processo administrativo quando a falta disciplinar, por sua natureza, possa determinar as penas de demissão, de demissão a bem do serviço público e de cassação de aposentadoria ou disponibilidade. A vigência esgota-se com a aplicação da pena disciplinar. A decisão deverá ser averbada no prontuário funcional.'),
('003.03.07.010', 'Vigência', '10 anos', 2, 'Lei Federal n. 10.406/2002 (Código Civil), art. 205; Lei Complementar Estadual n. 207/1979; Lei Complementar Estadual n. 922/2002; Lei Complementar Estadual n. 942/2003; Lei Estadual n. 10.261/1968. Será instaurada sindicância quando a falta disciplinar, por sua natureza, possa determinar as penas de repreensão, suspensão ou multa. A vigência esgota-se com a aplicação da pena disciplinar. A decisão deverá ser averbada no Prontuário funcional.'),
