('003.03.04.031', 'Vigência', '60 anos', 1, 'Constituição Federal, art. 201, § 9º; Portaria MTP n. 1.467/2022 ; Instrução Normativa Pres/INSS n.128/2022; Lei Estadual n. 10.261/1968; Comunicado GT n. 03/2003; Portaria SPPREV n. 102/2014; Comunicado SPPREV 2-2019. A vigência esgota-se com a entrega da CTC ao interessado.'),
