('003.03.03.003', '2 anos', NULL, 1, 'Trata-se de cópia, pois o documento é encaminhado à Secretaria de Estado do Emprego e Relações do Trabalho.'),
('003.03.03.004', 'Vigência', '5 anos', 1, 'Constituição Federal/1988; Decreto-Lei Federal n. 5.452/1943 (CLT). A vigência esgota-se com o rompimento do vínculo jurídico com o Estado.'),
('003.03.03.005', 'Vigência', '2 anos', 2, 'Decreto-Lei Federal n. 5.452/1943 (CLT). A vigência perdura até completar o livro.'),
