('003.03.04.033', 'Vigência', '10 anos', 1, 'Constituição Federal, art. 40, § 4º. Lei Federal n. 10.406/2002 (Código Civil), art. 205. A vigência esgota-se com a entrega da certidão negativa ou declaração remuneratória ao interessado.'),
